<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mini Bibliothèque</title><link rel="stylesheet" href="style.css"></head><body>
<header><h1>Mini Bibliothèque</h1><p>Un espace clair pour suivre les livres et les emprunts.</p></header><main>
<?php if($message): ?><div class="notice success"><?=htmlspecialchars($message)?></div><?php endif ?>
<section class="stats"><?php foreach(['Livres'=>'livres','Exemplaires'=>'exemplaires','Emprunts en cours'=>'emprunts'] as $label=>$key): ?><div><strong><?=$stats[$key]?></strong><span><?=$label?></span></div><?php endforeach ?></section>
<section class="grid"><form method="post"><h2>Ajouter un livre</h2><input type="hidden" name="action" value="book"><input name="titre" placeholder="Titre" required><input name="auteur" placeholder="Auteur" required><input name="categorie" placeholder="Catégorie"><input name="quantite" type="number" min="1" placeholder="Quantité" required><button>Ajouter</button></form>
<form method="post"><h2>Enregistrer un emprunteur</h2><input type="hidden" name="action" value="borrower"><input name="nom" placeholder="Nom" required><input name="telephone" placeholder="Téléphone" required><button>Enregistrer</button></form>
<form method="post"><h2>Nouvel emprunt</h2><input type="hidden" name="action" value="loan"><select name="livre_id" required><option value="">Livre</option><?php foreach($books as $book): if($book['disponibles']>0): ?><option value="<?=$book['id']?>"><?=htmlspecialchars($book['titre'])?> (<?=$book['disponibles']?>)</option><?php endif; endforeach ?></select><select name="emprunteur_id" required><option value="">Emprunteur</option><?php foreach($borrowers as $borrower): ?><option value="<?=$borrower['id']?>"><?=htmlspecialchars($borrower['nom'])?></option><?php endforeach ?></select><button>Emprunter</button></form></section>
<section><form class="search"><input name="q" value="<?=htmlspecialchars($query)?>" placeholder="Rechercher un titre ou auteur"><button>Rechercher</button></form><h2>Livres</h2><div class="table-wrap"><table><tr><th>Titre</th><th>Auteur</th><th>Catégorie</th><th>Disponibles</th><th>Actions</th></tr><?php foreach($books as $book): ?><tr><td><?=htmlspecialchars($book['titre'])?></td><td><?=htmlspecialchars($book['auteur'])?></td><td><?=htmlspecialchars($book['categorie'] ?: '-')?></td><td><?=$book['disponibles']?>/<?=$book['quantite']?></td><td><form class="inline" method="post"><input type="hidden" name="action" value="edit_book"><input type="hidden" name="id" value="<?=$book['id']?>"><input name="titre" value="<?=htmlspecialchars($book['titre'])?>" required><input name="auteur" value="<?=htmlspecialchars($book['auteur'])?>" required><input name="categorie" value="<?=htmlspecialchars($book['categorie'] ?? '')?>"><input name="quantite" type="number" min="1" value="<?=$book['quantite']?>" required><button>Modifier</button></form><form class="inline" method="post"><input type="hidden" name="action" value="delete_book"><input type="hidden" name="id" value="<?=$book['id']?>"><button>Supprimer</button></form></td></tr><?php endforeach ?></table></div></section>
<section><h2>Emprunts</h2><div class="table-wrap"><table><tr><th>Livre</th><th>Emprunteur</th><th>Statut</th><th>Action</th></tr><?php foreach($loans as $loan): ?><tr><td><?=htmlspecialchars($loan['titre'])?></td><td><?=htmlspecialchars($loan['emprunteur'])?></td><td><?=$loan['statut']?></td><td><?php if($loan['statut']==='en_cours'): ?><form method="post"><input type="hidden" name="action" value="return"><input type="hidden" name="id" value="<?=$loan['id']?>"><button>Retourner</button></form><?php else: ?><?=$loan['date_retour']?><?php endif ?></td></tr><?php endforeach ?></table></div></section></main></body></html>
